        app.maintenance_step(1, TYPED_OPERATION_RESULT_PAGE_BYTES).unwrap();
        assert_eq!(app.tool_cancellations.active_operation_count(), 1);
        for _ in 0..100_000 {
            if app.close_terminal_is_empty() {
                break;
