                    assert!(released_bytes <= TYPED_OPERATION_RESULT_PAGE_BYTES);
                }
                PluginCloseStep::Complete => break,
                PluginCloseStep::AwaitingInput { reason } => panic!("fairness fixture close awaited input: {reason}"),
